        slugify('hello', backend='invalid', algorithm='modern')

def test_modern_algo_invalid_algorithm():
    with pytest.raises(ValueError):
        slugify('hello', algorithm='invalid')

def test_modern_algo_bytes_input():
    assert slugify(b'hello world', algorithm='modern') == 'hello-world'






def test_modern_algo_hard_cut_at_boundary():
    assert slugify('ab', max_length=1, algorithm='modern') == 'a'
    assert slugify('a b', max_length=1, algorithm='modern') == 'a'
    assert slugify('a-b', max_length=1, algorithm='modern') == 'a'


def test_modern_algo_hard_cut_three_chars_with_delimiters():
    assert slugify('a-bc', max_length=3, algorithm='modern') == 'a-b'
    assert slugify('a bc', max_length=3, algorithm='modern') == 'a-b'
    assert slugify('ab c', max_length=3, algorithm='modern') == 'ab'




def test_modern_algo_stopwords_case_sensitivity():
    txt = 'Foo BAR baz'
    assert slugify(txt, stopwords=['bar'], lowercase=True, algorithm='modern') == 'foo-baz'
    assert slugify(txt, stopwords=['BAR'], lowercase=True, algorithm='modern') == 'foo-baz'
    assert slugify(txt, stopwords=['bar'], lowercase=False, algorithm='modern') == 'Foo-BAR-baz'
    assert slugify(txt, stopwords=['BAR'], lowercase=False, algorithm='modern') == 'Foo-baz'


def test_modern_algo_replacements_applied_in_order():
    assert slugify('hello [world]', replacements=[('[', '('), (']', ')')], algorithm='modern') == 'hello-world'
    assert slugify('hello [world]', replacements=[('[', '('), (']', ')')], replacement_stage='pre', algorithm='modern') == 'hello-world'
    assert slugify('hello [world]', replacements=[('[', '('), (']', ')')], replacement_stage='post', algorithm='modern') == 'hello-world'
    assert slugify('hello world', replacements=[('world', 'everyone')], algorithm='modern') == 'hello-everyone'
    assert slugify('hello world', replacements=[('world', 'everyone')], replacement_stage='pre', algorithm='modern') == 'hello-everyone'
    assert slugify('hello world', replacements=[('world', 'everyone')], replacement_stage='post', algorithm='modern') == 'hello-everyone'
    assert slugify('hello-[world]', replacements=[('-', '_'), ('[', '('), (']', ')')], algorithm='modern') == 'hello_world'

def test_modern_algo_html_entity_decoding():
    assert slugify('foo &amp; bar', algorithm='modern') == 'foo-bar'
    assert slugify('foo &amp; bar', entities=False, algorithm='modern') == 'foo-amp-bar'
    assert slugify('&#381;', decimal=True, algorithm='modern') == 'z'
    assert slugify('&#381;', decimal=False, algorithm='modern') == '381'
    assert slugify('&#x17D;', hexadecimal=True, algorithm='modern') == 'z'
    assert slugify('&#x17D;', hexadecimal=False, algorithm='modern') == 'x17d'



def test_modern_algo_allow_unicode_false_cyrillic():
    assert slugify('ЖЖЖ', algorithm='modern') == 'zhzhzh'



def test_modern_algo_backend_text_unidecode_used_when_unidecode_missing(monkeypatch):
    if 'unidecode' in __import__('sys').modules:
        monkeypatch.delitem(__import__('sys').modules, 'unidecode', raising=False)
    class FakeTextUnidecode:
        @staticmethod
        def unidecode(text):
            return text.replace('ž', 'z').replace('ł', 'l').replace('ť', 't').replace('ouč', 'ouc').replace('ký', 'ky').replace('ň', 'n')
    monkeypatch.setitem(__import__('sys').modules, 'text_unidecode', FakeTextUnidecode)
    assert slugify('žluťoučký', backend='text-unidecode', algorithm='modern') == 'z-lut-ouc-ky'


